SELECT CASE WHEN s.rating >= 3.9 THEN 'high' WHEN s.rating >= 1.5 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(DISTINCT ss.units) AS unique_products FROM store_sales ss LEFT JOIN products p ON ss.product_id = p.id LEFT JOIN suppliers s ON p.supplier_id = s.id GROUP BY CASE WHEN s.rating >= 3.9 THEN 'high' WHEN s.rating >= 1.5 THEN 'mid' ELSE 'low' END ORDER BY rating_bucket, unique_products DESC;
